    sage = { gid = 1402; };
    prometheus = { gid = 120; };
    www-data = { gid = 33; };
  };

  users.users = {
    reed = {
      isNormalUser = true;
      uid = 1401;
      group = "reed";
      home = "/home/reed";
      homeMode = "750";
      shell = "/bin/bash";
      hashedPassword = "!";
    };
    sage = {
      isNormalUser = true;
      uid = 1402;
      group = "sage";
      home = "/home/sage";
      homeMode = "750";
      shell = "/bin/bash";
      hashedPassword = "!";
    };
    prometheus = {
      isSystemUser = true;
      uid = 112;
      group = "prometheus";
      home = "/var/lib/prometheus";
      createHome = false;
      description = "Prometheus daemon,,,";
      shell = "/run/current-system/sw/bin/nologin";
    };
    www-data = {
      isSystemUser = true;
      uid = 33;
      group = "www-data";
      home = "/var/www";
      createHome = false;
      description = "www-data";
      shell = "/run/current-system/sw/bin/nologin";
    };
  };

  environment.shells = [ "/bin/bash" ];

  system.activationScripts = {
    binbash = {
      deps = [ ];
      text = ''
        ln -sfn ${pkgs.bashInteractive}/bin/bash /bin/bash
