cmd='curl -s http://127.0.0.1:9090/api/v1/status/config | python3 -c "import json,sys;print(json.load(sys.stdin)[\"data\"][\"yaml\"])"; echo ===AM; curl -s http://127.0.0.1:9093/api/v2/status | python3 -c "import json,sys;d=json.load(sys.stdin);print(d[\"config\"][\"original\"])"; echo ===RULES; curl -s http://127.0.0.1:9090/api/v1/rules | python3 -c "import json,sys;[print(g[\"name\"],r[\"name\"],r.get(\"type\")) for g in json.load(sys.stdin)[\"data\"][\"groups\"] for r in g[\"rules\"]]"; echo ===TARGETS; curl -s "http://127.0.0.1:9090/api/v1/targets" | python3 -c "import json,sys;[print(t[\"labels\"].get(\"job\"),t[\"scrapeUrl\"],t[\"health\"]) for t in json.load(sys.stdin)[\"data\"][\"activeTargets\"]]"'
R "$cmd" > /tmp/ref_prom.txt 2>&1; N "$cmd" > /tmp/new_prom.txt 2>&1; diff /tmp/ref_prom.txt /tmp/new_prom.txt | head -80; echo "DIFF EXIT $?"; wc -l /tmp/ref_prom.txt /tmp/new_prom.txt

