# As on the reference: the master process runs as root (it reads the root-only
# TLS key), and the `user www-data;` directive drops the workers to www-data.
# The NixOS unit's sandbox assumes a non-root master, so widen it for that.
systemd.services.nginx.serviceConfig = {
  User = lib.mkForce "root";
  Group = lib.mkForce "root";
  CapabilityBoundingSet = lib.mkForce [
    "CAP_NET_BIND_SERVICE"
    "CAP_SYS_RESOURCE"
    "CAP_SETUID"
    "CAP_SETGID"
    "CAP_CHOWN"
    "CAP_DAC_OVERRIDE"
  ];
  SystemCallFilter = lib.mkForce [ ];
};

arguments.new_string:
